// Data teks untuk latihan mengetik & soal HOTS berpikir komputasional
// Materi dibedakan per tingkat kelas:
//  - Kelas 7: pengenalan komputer & dampak teknologi (paling dasar)
//  - Kelas 8: pengenalan konsep dasar berpikir komputasional di kehidupan sehari-hari
//  - Kelas 9: laporan terstruktur dengan judul, sub-judul (#, ##, ###) + isu teknologi modern

export type GradeLevel = '7A' | '7B' | '7C' | '8A' | '8B' | '8C' | '9A' | '9B'

export interface Question {
  id: number
  question: string
  options: string[]
  correctAnswer: number
  explanation: string
  category: string
  // ── Bug #2 fix: add optional imageUrl so gambar soal can render ──
  // The API /api/content/questions returns imageUrl from the Prisma
  // Question model (imageUrl String?). Without this field declared,
  // TypeScript errors out and the runtime check `currentQ.imageUrl && (...)`
  // always evaluates to falsy (undefined), preventing images from rendering.
  imageUrl?: string | null
}

