// Helper functions
export function getTypingText(gradeLevel: GradeLevel): string {
  return TYPING_TEXTS[gradeLevel] ?? TYPING_TEXTS['7A']
}

export function getQuestions(gradeLevel: GradeLevel | string): Question[] {
  // ── FIX Bug A: Jangan fallback ke soal SMP untuk siswa SMK ──
  // Sebelumnya: "11DKV".charAt(0) = '1' → QUESTIONS_BY_GRADE['1'] undefined
  // → fallback ke QUESTIONS_BY_GRADE['7'] (soal SMP kelas 7 — SALAH subjek).
  //
  // Sekarang: Untuk SMK (kelas 11DKV / 12DKV / atau string yang dimulai
  // dengan "11"/"12"), return [] langsung. Soal SMK HARUS datang dari
  // database via /api/content/questions, bukan dari fallback statis SMP.
  // Fallback [] akan menampilkan pesan "soal tidak tersedia" di UI,
  // bukan menampilkan soal SMP yang salah.
  const kelas = String(gradeLevel || '')
  if (kelas.startsWith('11') || kelas.startsWith('12')) {
    return []
  }
  const tier = kelas.charAt(0) as '7' | '8' | '9'
  return QUESTIONS_BY_GRADE[tier] ?? []
}

// Cek apakah teks menggunakan format markdown (kelas 9)
export function isStructuredText(gradeLevel: GradeLevel): boolean {
  return gradeLevel.startsWith('9')
}

// Hitung jumlah heading (#, ##, ###) di teks markdown
export function countHeadings(text: string): { h1: number; h2: number; h3: number } {
  const lines = text.split('\n')
  let h1 = 0, h2 = 0, h3 = 0
  for (const line of lines) {
    if (line.startsWith('### ')) h3++
    else if (line.startsWith('## ')) h2++
    else if (line.startsWith('# ')) h1++
  }
  return { h1, h2, h3 }
}

// Hitung jumlah heading di teks sumber
export function getSourceHeadings(gradeLevel: GradeLevel): { h1: number; h2: number; h3: number } {
  return countHeadings(getTypingText(gradeLevel))
}

